import{_ as t,o as a,c as s,a2 as o}from"./chunks/framework.BM5YPQmL.js";const g=JSON.parse('{"title":"Debug handbook","description":"","frontmatter":{},"headers":[],"relativePath":"dev/debug-handbook.md","filePath":"dev/debug-handbook.md"}'),i={name:"dev/debug-handbook.md"};function n(d,e,r,l,c,h){return a(),s("div",null,[...e[0]||(e[0]=[o(`<h1 id="debug-handbook" tabindex="-1">Debug handbook <a class="header-anchor" href="#debug-handbook" aria-label="Permalink to &quot;Debug handbook&quot;">​</a></h1><p>The complete field guide to extracting evidence from an OCOS machine: serial capture, the kernel log ring, crash dumps and register snapshots, and - most importantly - a methodology for the times nothing is obviously wrong. Companion pages: <a href="./debug-interfaces.html">debug-interfaces.md</a> inventories the ~93 test-stub programs; <a href="./qemu-testing.html">qemu-testing.md</a> covers QEMU-specific behaviors; <a href="./debugging.html">debugging.md</a> is the short entry point.</p><h2 id="_1-serial-extraction" tabindex="-1">1. Serial extraction <a class="header-anchor" href="#_1-serial-extraction" aria-label="Permalink to &quot;1. Serial extraction&quot;">​</a></h2><p>Every boot line, panic banner and captured op mirrors to COM1 (115200 8N1, polled). Serial is the <em>authoritative</em> channel (VGA is best-effort).</p><p><strong>QEMU</strong>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>make run-bios          # -display none -serial mon:stdio -snapshot</span></span>
<span class="line"><span># or explicitly:</span></span>
<span class="line"><span>qemu-system-x86_64 -m 512M -cdrom build/opencube.iso \\</span></span>
<span class="line"><span>    -netdev user,id=n1 -device e1000,netdev=n1 \\</span></span>
<span class="line"><span>    -display none -serial mon:stdio          # interactive (monitor on Ctrl-A C)</span></span>
<span class="line"><span>qemu-system-x86_64 ... -serial file:boot.log # capture to a file</span></span>
<span class="line"><span>qemu-system-x86_64 ... -serial stdio -d int,cpu_reset -D qemu.log</span></span></code></pre></div><p>The pexpect harnesses use <code>-serial mon:stdio</code> with <code>encoding=&quot;latin-1&quot;</code> so every byte survives; the prompt regex is <code>(?:ush&gt;|oc&gt;)\\s</code> (override with <code>OC_PROMPT</code>).</p><p><strong>Real hardware</strong>: a USB-TTL adapter on the COM1 header. The serial tee encoding follows the <code>serial_encoding</code> setting (<code>utf8|gbk</code>, display op 17) - set <code>gbk</code> when your terminal is a GB2312-era console.</p><h2 id="_2-reading-the-kernel-log-ring" tabindex="-1">2. Reading the kernel log ring <a class="header-anchor" href="#_2-reading-the-kernel-log-ring" aria-label="Permalink to &quot;2. Reading the kernel log ring&quot;">​</a></h2><p>The 1024-entry ring (24-entry bootstrap ring before <code>klog_grow()</code>) records EVERYTHING unconditionally; the live channels (serial + console) are gated by the live level (default INFO). The replay ops apply the active filter to what they show.</p><p>Line format (identical in ring replay, <code>/var/log/kernel.log</code>, and live channels):</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[   12.345] WARN  net: link up (e1000)</span></span>
<span class="line"><span>[SSS.mmm]    LEVEL module: message</span></span></code></pre></div><ul><li>timestamp = seconds.milliseconds since <code>klog_init</code> (<code>core_timer_now_ms</code>; 0.000 pre-PIT),</li><li>level is one of DEBUG 0 / INFO 1 / WARN 2 / ERROR 3 / FATAL 4 (rendered <code>DEBUG/INFO/WARN /ERROR/FATAL</code> in the columns),</li><li>module is the 12-char tag (<code>net</code>, <code>health</code>, <code>ocire</code>, <code>klogtest</code>, ...).</li></ul><p>Usage table (apps <code>dmesg</code>, <code>logcat</code>, <code>logctl</code>):</p><table tabindex="0"><thead><tr><th>Command</th><th>Grammar</th><th>What it does</th></tr></thead><tbody><tr><td><code>dmesg</code></td><td><code>dmesg [N]</code></td><td>replay the ring tail (default 30, 1..1024 lines) through the active filter; footer <code>-- &lt;shown&gt; lines (ring &lt;count&gt;/1024, dropped &lt;d&gt;) --</code></td></tr><tr><td><code>logcat</code></td><td><code>logcat -l &lt;lvl&gt; -m &lt;mod&gt; -k &lt;key&gt; -t &lt;sec&gt; -n &lt;N&gt; [-f]</code></td><td>filtered replay; <code>-l</code> debug/info/warn/error/fatal or 0-4, <code>-m</code> module exact, <code>-k</code> keyword substring, <code>-t</code> seconds cutoff, <code>-n</code> count; <code>-f</code> follows live at a 10 Hz poll (ENTER exits)</td></tr><tr><td><code>logctl status</code></td><td></td><td>ring count, dropped, live level + per-level mask, file bytes/rotate info, filter state</td></tr><tr><td><code>logctl level [-1..4]</code></td><td></td><td>set the live level (-1 mutes live channels; ring still records)</td></tr><tr><td><code>logctl enable|disable &lt;level&gt;</code></td><td></td><td>per-level emission switches</td></tr><tr><td><code>logctl clear</code></td><td></td><td>reset the ring</td></tr><tr><td><code>logctl flush</code></td><td></td><td>append unsynced entries to <code>/var/log/kernel.log</code></td></tr><tr><td><code>logctl rotate</code></td><td></td><td>kernel.log -&gt; kernel.log.1 (keep 3)</td></tr><tr><td><code>logctl threshold &lt;512..16777216&gt;</code></td><td></td><td>rotation threshold (default 1048576)</td></tr><tr><td><code>logctl export [path]</code></td><td></td><td>dump to <code>/var/log/kernel-export.log</code></td></tr><tr><td><code>logctl filter clear | [level] [module] [keyword]</code></td><td></td><td>set/clear the active filter (&#39;-&#39; = any); applies to live channels AND dmesg/logcat replays</td></tr><tr><td><code>logctl test</code></td><td></td><td>emit 5 lines, one per level, module <code>klogtest</code> - the filter verification tool</td></tr></tbody></table><p>The on-disk channel (<code>/var/log/kernel.log</code>, 1 MiB rotation x3) is an emit hook installed by <code>klog_on_mount()</code> after the first fs mounts; it appends every not-yet-synced entry and auto-rotates. IRQ-context writers skip the FILE channel (deferred to the next task-context writer/flush/timer kick).</p><h2 id="_3-crash-evidence" tabindex="-1">3. Crash evidence <a class="header-anchor" href="#_3-crash-evidence" aria-label="Permalink to &quot;3. Crash evidence&quot;">​</a></h2><h3 id="_3-1-the-panic-banner-what-to-send-in-a-report" tabindex="-1">3.1 The panic banner (what to send in a report) <a class="header-anchor" href="#_3-1-the-panic-banner-what-to-send-in-a-report" aria-label="Permalink to &quot;3.1 The panic banner (what to send in a report)&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>*** KERNEL PANIC: &lt;reason&gt; [task=&lt;name&gt;] ***</span></span>
<span class="line"><span>kernel: Open Cube OS &lt;version&gt; (build 0x&lt;hex&gt;)</span></span>
<span class="line"><span>source: exception &lt;n&gt; (&lt;name&gt;) err=0x&lt;hex&gt;</span></span>
<span class="line"><span>&lt;task line&gt;</span></span>
<span class="line"><span>&lt;register dump: 4x4 grid r15..rax + rip/cs/ss/rflags/rsp/int/err [+ cr2] + cr3&gt;</span></span>
<span class="line"><span>&lt;traceback: rbp chain + stack scan&gt;</span></span>
<span class="line"><span>&lt;policy: HALT or REBOOT&gt;</span></span></code></pre></div><p>Variants you may see: <code>[KERNEL STACK OVERFLOW: exhausted, task=&lt;name&gt;]</code> (stack-overflow attribution); <code>core dump: skipped in #DF mode</code> (#DF is handled minimally at dispatcher depth with one static serial line - no record, no dump, no flush, stated in KNOWN_ISSUES); <code>*** NESTED PANIC INSIDE PANIC - HALTING ***</code>; <code>*** CONTAINED: &lt;what&gt; - isolated, kernel continues ***</code> (a panic handler claimed recovery).</p><h3 id="_3-2-crashlog-the-32-slot-ring" tabindex="-1">3.2 crashlog - the 32-slot ring <a class="header-anchor" href="#_3-2-crashlog-the-32-slot-ring" aria-label="Permalink to &quot;3.2 crashlog - the 32-slot ring&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ush&gt; crashlog          # each entry:</span></span>
<span class="line"><span>[i] &lt;src-name&gt; ring=N err=0x.. rip=0x.. rsp=0x.. [cr2=0x..] [@&lt;rtc&gt;s | @tick=N] [task=&lt;name&gt;] [pid=N]</span></span>
<span class="line"><span>ush&gt; crashlog flush    # append all entries to /var/log/crash.log</span></span></code></pre></div><p>Source names: the exception name (<code>#PF Page Fault</code>, ...) or a synthetic source - PANIC 32 / WDT 33 / ASSERT 34 / CONTAINED 35 / STACKOVF 36. Empty: <code>crashlog: no exceptions recorded</code>.</p><h3 id="_3-3-dumpinfo-the-ocdump01-image" tabindex="-1">3.3 dumpinfo + the OCDUMP01 image <a class="header-anchor" href="#_3-3-dumpinfo-the-ocdump01-image" aria-label="Permalink to &quot;3.3 dumpinfo + the OCDUMP01 image&quot;">​</a></h3><p><code>dumpinfo</code> reports the core-dump buffer status. The saved <code>/var/crash/core.dump</code> starts with:</p><div class="language-c vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">char</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> magic</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">8</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">];</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">            /* &quot;OCDUMP01&quot; */</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">u32 hdr_len;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">              /* sizeof(oc_dump_hdr_t) */</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">u32 image_len;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">            /* total bytes captured */</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">u64 build;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                /* OC_KERNEL_BUILD */</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">char</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> version</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">24</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">];</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">         /* OC_RELEASE_VERSION */</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">char</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> reason</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">40</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]; u64 jiffies; u64 rtc_epoch;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">u64 cr3; u64 pte_count; u32 tid, pid; u32 ring; </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">char</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> task</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">16</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">];</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">u64 stack_base, stack_size, stack_rsp; u32 stack_copy_len; u32 regs_present;</span></span></code></pre></div><p>followed by regs (22 u64), task block, the 4 KiB stack window and the page-table scan. Without any filesystem the first 2048 bytes are hex-dumped to serial. <code>crashtest dump</code> captures one without panicking - use it to validate your capture wiring before you need it.</p><h3 id="_3-4-reading-the-register-snapshot" tabindex="-1">3.4 Reading the register snapshot <a class="header-anchor" href="#_3-4-reading-the-register-snapshot" aria-label="Permalink to &quot;3.4 Reading the register snapshot&quot;">​</a></h3><p>The dump&#39;s 22 u64s are <code>arch_irq_frame_t</code> (r15..rax, int_no, error_code, rip, cs, rflags, rsp, ss). Per exception class:</p><table tabindex="0"><thead><tr><th>Exception</th><th>Field(s) that matter</th><th>Typical meaning</th></tr></thead><tbody><tr><td>#PF (14)</td><td><code>cr2</code> = faulting address; error_code bit0 (P)</td><td>P=0: not-present (NULL/wild pointer, or stack growth below RSP within limits); P=1: protection violation - never remapped, a real bug; U/S bit tells ring; I/D bit = instruction fetch (NX)</td></tr><tr><td>#GP (13)</td><td>error_code selector index</td><td>bad descriptor/privilege - classic ring-3 I/O attempt (IOPB denies all ports)</td></tr><tr><td>#DE (0), #OF (4)</td><td>rax/operands</td><td>divide/overflow at rip</td></tr><tr><td>#UD (6)</td><td>rip</td><td>executing garbage - check the traceback&#39;s code-range filter</td></tr><tr><td>#DF (8)</td><td>rsp vs task stack window</td><td>rsp at/below stack bottom =&gt; stack exhaustion attribution; #DF prints only the minimal line</td></tr><tr><td>#DB/NMI/#BP (1/2/3)</td><td>-</td><td>handled on IST2; kills of ring-3 origin run on the exit stack</td></tr><tr><td>watchdog (33)</td><td>task line</td><td>heartbeat starved 15 s while armed</td></tr><tr><td>stackovf (36)</td><td>task name</td><td>kthread guard page hit</td></tr></tbody></table><p><code>rip</code> inside a task&#39;s guard page or below its stack base is the smoking gun for stack overflow; the traceback prints the rbp chain plus stack-scan candidates filtered by <code>looks_like_code</code>.</p><h2 id="_4-silent-failure-methodology" tabindex="-1">4. Silent-failure methodology <a class="header-anchor" href="#_4-silent-failure-methodology" aria-label="Permalink to &quot;4. Silent-failure methodology&quot;">​</a></h2><p>When there is no panic, no banner, no error line - work this ladder top to bottom.</p><h3 id="_4-1-the-health-alarms-objective-state" tabindex="-1">4.1 The health alarms (objective state) <a class="header-anchor" href="#_4-1-the-health-alarms-objective-state" aria-label="Permalink to &quot;4.1 The health alarms (objective state)&quot;">​</a></h3><p><code>health</code> prints cpu/memory/tasks/disk/network plus the <code>alarms:</code> line. The three bits, sampled every second, deduplicated (one ERROR per crossing, re-armed when the metric recovers):</p><table tabindex="0"><thead><tr><th>Alarm</th><th>Trigger</th><th>Meaning</th></tr></thead><tbody><tr><td><code>MEMORY&gt;90%</code></td><td><code>mem_used*100/mem_total &gt; 90</code></td><td>PMM+heap pressure - check <code>mem</code>, <code>frag</code>, <code>heap</code></td></tr><tr><td><code>TASKS&gt;64</code></td><td>active tasks &gt; 64</td><td>task-slot leak - <code>ps</code>/<code>sched</code>, look for unreaped exits</td></tr><tr><td><code>CPU-LOCKED</code></td><td>busy &gt;= 90% for 10 consecutive samples</td><td>a spinner/pinned loop - <code>sched</code>, <code>nice</code> the suspect down</td></tr></tbody></table><h3 id="_4-2-the-log-ring-not-the-live-console" tabindex="-1">4.2 The log ring (not the live console) <a class="header-anchor" href="#_4-2-the-log-ring-not-the-live-console" aria-label="Permalink to &quot;4.2 The log ring (not the live console)&quot;">​</a></h3><p>The ring records unconditionally even when the live level or a filter hides lines: <code>logctl level 0</code> (open the live gate), then <code>dmesg 200</code>. <code>logctl test</code> proves the pipeline itself works. If the ring is empty at FATAL for a subsystem that &quot;did nothing&quot;, that subsystem may use the honest-skip convention (4.5) rather than logging.</p><h3 id="_4-3-the-kcap-trap-output-that-vanished" tabindex="-1">4.3 The kcap trap (output that vanished) <a class="header-anchor" href="#_4-3-the-kcap-trap-output-that-vanished" aria-label="Permalink to &quot;4.3 The kcap trap (output that vanished)&quot;">​</a></h3><p><strong>The single most common silent-failure cause in this codebase.</strong> While an L1SVC capture is active, the capture hook IS the console hook: characters collect into the caller&#39;s buffer and BOTH the framebuffer and the serial tee are suppressed. Consequences:</p><ul><li>A captured op that internally triggers live output (a nested live session, a sleep-park, a klog FATAL that would have hit the serial) will look like the system went console-silent.</li><li>Historical live-caught cases: <code>power sleep</code> captured installed the capture hook for the whole park and swallowed every console line during an OCIRE-supervised boot; <code>sshd</code> had to route direct so <code>net_sshd_log</code> reaches the console live.</li><li>Rule: ops that park or own a live session route DIRECT (<code>out[0]=0; return fn(arg);</code>); only one-shot text renderers run captured. If you are adding an op and its output &quot;disappears&quot;, check the routing style first (<a href="./writing-services.html">writing-services.md</a>).</li></ul><h3 id="_4-4-return-value-conventions" tabindex="-1">4.4 Return-value conventions <a class="header-anchor" href="#_4-4-return-value-conventions" aria-label="Permalink to &quot;4.4 Return-value conventions&quot;">​</a></h3><ul><li>Syscalls return <code>&gt;= 0</code> on success, negative on error (<code>-1</code> for most paths); <code>SYS_L1SVC</code> returns 0 for any <em>routed</em> call - the operation&#39;s own failure text is inside <code>out</code> (see <a href="./syscall-reference.html">syscall-reference.md</a> section 1.5/4).</li><li>Driver/block/nic ops return 0 (or positive byte counts) on success and negative on error.</li><li>If a wrapper prints <code>&lt;name&gt;: svc_call_failed</code>, the <em>category or op did not route</em> - a typo&#39;d op number, a kernel-only service, or (cat 18) a non-guard caller refused: <code>ocire: refused (guard-only channel)</code>.</li></ul><h3 id="_4-5-the-honest-skip-mode" tabindex="-1">4.5 The &quot;honest skip&quot; mode <a class="header-anchor" href="#_4-5-the-honest-skip-mode" aria-label="Permalink to &quot;4.5 The &quot;honest skip&quot; mode&quot;">​</a></h3><p>The tree deliberately distinguishes FAIL from SKIP. Recognize these strings and do not chase them as bugs:</p><ul><li><code>... =&gt; SKIPPED</code> (e.g. <code>[sample_rate_test] no sound cards registered =&gt; SKIPPED</code>) - precondition absent, test not run.</li><li><code>honest FAIL</code> (e.g. <code>oneshot: arm failed (honest FAIL)</code>) - the operation really was attempted and refused.</li><li><code>: SKIP - see the dedicated halt session</code> (halt/reboot tests - destructive, live halt deliberately not observed).</li><li><code>watchdog hw: none (no WDAT table, no Intel TCO LPC)</code> - the probe honestly reports absence (default <code>pc</code> machine has no TCO; use q35).</li><li><code>wifi scan</code> under QEMU prints the honest &quot;no radio&quot; output.</li><li><code>ocire: embed inactive (normal boot)</code> - cat 18 is dormant on a GRUB boot; that is correct behavior.</li><li><code>DesignWare: not present on this platform (honest skip)</code>.</li></ul><h3 id="_4-6-deadlock-vs-hang" tabindex="-1">4.6 Deadlock vs. hang <a class="header-anchor" href="#_4-6-deadlock-vs-hang" aria-label="Permalink to &quot;4.6 Deadlock vs. hang&quot;">​</a></h3><ul><li>The soft watchdog (15 s, slot 0 &quot;system-heartbeat&quot;) panics with source WDT <em>only when armed and starved</em>; the shell line editor kicks it on every key - a machine that answers keystrokes is alive at the scheduler level.</li><li><code>ps</code>/<code>sched</code>: a task stuck in TASK_BLOCKED with no waiter is your candidate; <code>syncstat</code> shows primitive op counters.</li><li>The boot-state monitor&#39;s <code>/HANGAT</code> injection (below) exercises the deliberate-hang path end to end.</li></ul><h2 id="_5-fault-injection-tools" tabindex="-1">5. Fault injection tools <a class="header-anchor" href="#_5-fault-injection-tools" aria-label="Permalink to &quot;5. Fault injection tools&quot;">​</a></h2><h3 id="_5-1-crashtest-the-8-modes" tabindex="-1">5.1 crashtest - the 8 modes <a class="header-anchor" href="#_5-1-crashtest-the-8-modes" aria-label="Permalink to &quot;5.1 crashtest - the 8 modes&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>usage: crashtest panic|exc|pf|assert|wd|ovf|dump|policy [halt|reboot]</span></span>
<span class="line"><span>  panic   : kernel_panic() direct</span></span>
<span class="line"><span>  exc     : ring-0 #UD exception</span></span>
<span class="line"><span>  pf      : ring-0 unmapped-address write fault</span></span>
<span class="line"><span>  assert  : OC_ASSERT(0)</span></span>
<span class="line"><span>  wd      : forced watchdog timeout</span></span>
<span class="line"><span>  ovf     : kernel stack overflow (guard page)</span></span>
<span class="line"><span>  dump    : capture a core dump without panicking</span></span>
<span class="line"><span>  policy  : show/set the after-panic policy</span></span></code></pre></div><ul><li><code>exc</code> executes <code>__asm__ volatile(&quot;.byte 0x0F, 0x0B\\n&quot;)</code> (#UD).</li><li><code>pf</code> writes to 0x700000000000 (PML4[224], guaranteed not-present - a C NULL-deref would not work: UB folds to ud2 AND page 0 is identity-mapped).</li><li><code>panic|exc|pf|assert|wd|ovf</code> REALLY crash the kernel (v2.2.0 behaviour); <code>policy</code>/<code>dump</code>/usage are safe. Unknown variant: <code>crashtest: unknown variant &#39;x&#39; (try: crashtest help)</code>.</li></ul><p>Use <code>crashtest dump</code> + <code>dumpinfo</code> + <code>crashlog</code> to prove your evidence chain before a real failure; use the crashing modes to test panic policy and the OCBL/OCIRE relay.</p><h3 id="_5-2-msitest-msi-injection" tabindex="-1">5.2 msitest - MSI injection <a class="header-anchor" href="#_5-2-msitest-msi-injection" aria-label="Permalink to &quot;5.2 msitest - MSI injection&quot;">​</a></h3><p><code>msitest</code> (diag op 21) triggers real MSI/MSI-X interrupt delivery (LAPIC vectors 0x30..0x6F) - use it to prove the MSI path (enables, vector registration, EOI) independently of device traffic.</p><h3 id="_5-3-hangat-the-boot-stage-hang-injector" tabindex="-1">5.3 /HANGAT - the boot-stage hang injector <a class="header-anchor" href="#_5-3-hangat-the-boot-stage-hang-injector" aria-label="Permalink to &quot;5.3 /HANGAT - the boot-stage hang injector&quot;">​</a></h3><p>Kernel cmdline <code>oc.hang=&lt;stage&gt;</code> halts the boot <em>after</em> the named boot-state stage write + watchdog arm, exercising the real 6300ESB relay chain (stage monitor writes, heartbeats stop, the hardware resets, OCBL judges, the record routes to OCIRE). <code>oc.stmon=off</code> disables the whole state monitor. Stage names from <code>ocst_stage_name</code>: BOOT, KM_AIN_ENTERED, SCHED_READY, DRIVERS_READY, SERVICES_READY, L1_LAUNCHED, L1_READY.</p><h3 id="_5-4-watchdog-test-injectors" tabindex="-1">5.4 watchdog test injectors <a class="header-anchor" href="#_5-4-watchdog-test-injectors" aria-label="Permalink to &quot;5.4 watchdog test injectors&quot;">​</a></h3><p><code>watchdog test kill|panic|log</code> spawns a <code>wd-starve</code> kthread (priority 15) that registers itself monitored for 3 s and never feeds - &quot;expect the policy in 3 s&quot; (task killed / kernel panic / ERROR log per the registered policy).</p><h2 id="_6-host-side-tools" tabindex="-1">6. Host-side tools <a class="header-anchor" href="#_6-host-side-tools" aria-label="Permalink to &quot;6. Host-side tools&quot;">​</a></h2><ul><li><code>build/opencube_base.elf</code> is the pre-<code>strip</code> symbol carrier (the pipeline links with <code>-g</code>, then strips the final ELF).</li><li>gdb: <code>qemu ... -s -S</code>, then <code>target remote localhost:1234</code>, <code>break kmain</code>, <code>continue</code>.</li><li><code>-d int,cpu_reset,guest_errors -D qemu.log</code> logs interrupts, resets and errors.</li><li><code>make test</code> runs the host unit harnesses (crypto vectors, tar, gzip, MB2 parse, CUBIC, block-512 gate, ...) - much faster to iterate on than a boot loop; several harnesses use ASAN locally.</li><li>Reproducible builds mean a crash reproduced twice is the same bytes - no heisen-builds across attempts (<code>make reproducible-check</code>).</li></ul>`,61)])])}const u=t(i,[["render",n]]);export{g as __pageData,u as default};
